      "offers": { "@type": "Offer", "price": "0", "priceCurrency": "USD" },
      "publisher": { "@type": "Organization", "name": "Metazivo", "url": "https://metazivo.com/" }
    },
    {
      "@type": "BreadcrumbList",
      "itemListElement": [
        { "@type": "ListItem", "position": 1, "name": "Home", "item": "https://metazivo.com/" },
        { "@type": "ListItem", "position": 2, "name": "Free Tools", "item": "https://metazivo.com/free-tools" },
        { "@type": "ListItem", "position": 3, "name": "Meta Tag Checker", "item": "https://metazivo.com/tools/meta-tag-checker/" }
      ]
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        { "@type": "Question", "name": "Do meta tags affect Google rankings?", "acceptedAnswer": { "@type": "Answer", "text": "The title tag counts as a ranking signal. The meta description does not lift rankings directly but a good one raises clicks. The meta keywords tag is ignored. So spend your effort on titles first and descriptions second." } },
        { "@type": "Question", "name": "Why does Google show a different title than mine?", "acceptedAnswer": { "@type": "Answer", "text": "Google may rewrite a title when it runs too long or looks stuffed or does not match the query or repeats across pages. You cannot force it. A clear title that matches the main topic of the page gives you the best odds of keeping it." } },
        { "@type": "Question", "name": "Why does my OG image not update on Facebook or LinkedIn?", "acceptedAnswer": { "@type": "Answer", "text": "Platforms store a copy of your card. After fixing the tags use the Facebook Sharing Debugger or the LinkedIn Post Inspector to fetch the page again. Also confirm the image path is absolute and loads. Then share a fresh link to test." } },
        { "@type": "Question", "name": "Do I need both Open Graph and Twitter Card tags?", "acceptedAnswer": { "@type": "Answer", "text": "Open Graph alone works because X falls back to it. Add Twitter Card tags when you want a different card style on X or full control over that preview. For most small sites one clean Open Graph set is enough to start." } },
        { "@type": "Question", "name": "How many meta tags does a page need at minimum?", "acceptedAnswer": { "@type": "Answer", "text": "Title and description and viewport and charset form the base. For sharing add og:title and og:description and og:image plus a Twitter Card tag. A healthy page lands around 7 to 10 tags. More is not better if the extras repeat each other." } },
        { "@type": "Question", "name": "Can I check a staging page or page behind login?", "acceptedAnswer": { "@type": "Answer", "text": "The checker fetches like an outside visitor. Pages behind a login or a staging password or blocked by robots rules return an error or an empty result. Use View Page Source in your browser while logged in. Or open the staging site briefly to test." } },
        { "@type": "Question", "name": "Do AI search tools read meta tags?", "acceptedAnswer": { "@type": "Answer", "text": "Many AI answer tools and preview systems reuse page metadata but no platform publishes a full rule set. Clear titles and descriptions cost nothing and can only help. Treat it as a bonus and not a promise." } },
        { "@type": "Question", "name": "How often should I re-check meta tags?", "acceptedAnswer": { "@type": "Answer", "text": "Check after every theme update and plugin update and migration or template change. On a stable site a monthly pass on your key templates is enough. Also run a quick check right after you publish any big new page." } },
        { "@type": "Question", "name": "What size should og:image be?", "acceptedAnswer": { "@type": "Answer", "text": "Use 1200 by 630 pixels for wide cards. That matches the 1.91 to 1 ratio most platforms crop to. Keep key content near the center. Use JPG or PNG hosted on HTTPS and keep the file light so it loads fast for the platform." } },
        { "@type": "Question", "name": "How do I fix duplicate meta tags in WordPress with Yoast?", "acceptedAnswer": { "@type": "Answer", "text": "View the page source and search for og:title to count the copies. Then check the Yoast social settings and any other SEO or social plugin and the theme header file. Keep one source. Clear your cache plugin and CDN and run the URL again." } }
      ]
    }
  ]
}

{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebApplication",
      "name": "Free Keyword Density Checker",
      "url": "https://metazivo.com/tools/keyword-density-checker/",
      "applicationCategory": "BusinessApplication",
      "operatingSystem": "Any",
      "description": "Free keyword density checker to analyze keyword density and spot overuse.",
      "publisher": { "@type": "Organization", "name": "Metazivo", "url": "https://metazivo.com/" }
    },
    {
      "@type": "BreadcrumbList",
      "itemListElement": [
        { "@type": "ListItem", "position": 1, "name": "Home", "item": "https://metazivo.com/" },
        { "@type": "ListItem", "position": 2, "name": "Free Tools", "item": "https://metazivo.com/free-tools" },
        { "@type": "ListItem", "position": 3, "name": "Keyword Density Checker", "item": "https://metazivo.com/tools/keyword-density-checker/" }
      ]
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        { "@type": "Question", "name": "Does Google use keyword density as a ranking factor?", "acceptedAnswer": { "@type": "Answer", "text": "Not as a fixed target. Google spam policies name keyword stuffing but no official page sets an ideal percentage. Search systems read context and synonyms and topic coverage. Density works better as a warning light. A very high number can signal stuffing while a normal one tells you little about quality." } },
        { "@type": "Question", "name": "Can low density hurt rankings?", "acceptedAnswer": { "@type": "Answer", "text": "Rarely on its own. A page with a low percentage can still rank if it covers the topic and matches intent. It becomes a problem only when the main phrase and its variants barely appear and the page drifts off topic. Name the topic clearly in the title and opening paragraph." } },
        { "@type": "Question", "name": "Do keywords in headings count more than body text?", "acceptedAnswer": { "@type": "Answer", "text": "Headings usually give search engines a clearer topic signal than a line in the middle of a paragraph. Most checkers treat all text the same though. Use the report to balance the body and place your main phrase in a heading by hand." } },
        { "@type": "Question", "name": "Does density work the same on 300-word and 3000-word pages?", "acceptedAnswer": { "@type": "Answer", "text": "No. Short pages swing wildly because one extra use shifts the percentage a lot. On a 300 word page one more repeat adds about 0.3 points. On a 3000 word page it adds about 0.03. Benchmark against pages of similar length." } },
        { "@type": "Question", "name": "Is it safe to paste unpublished client content?", "acceptedAnswer": { "@type": "Answer", "text": "This checker runs in your browser using JavaScript so your text is not sent to a server. Still follow your own client agreements. If a contract limits third party tools ask first." } },
        { "@type": "Question", "name": "How do I check a competitor page?", "acceptedAnswer": { "@type": "Answer", "text": "Open the page and copy only the main body text. Skip menus and footers. Paste it into the checker and read the phrase tables. Repeat with three ranking pages to see a pattern. Use it for research only and never reuse their wording." } },
        { "@type": "Question", "name": "Does density matter for ChatGPT or Perplexity citations?", "acceptedAnswer": { "@type": "Answer", "text": "Not directly. AI answer engines tend to pick pages that state clear facts and define terms plainly. Repeating a phrase adds nothing citable. Focus on precise definitions and named entities and tidy structure. Keep density normal so stuffing does not hurt readability." } },
        { "@type": "Question", "name": "How do I calculate density by hand in Excel or Google Sheets?", "acceptedAnswer": { "@type": "Answer", "text": "Count the words with a formula that splits the text on spaces. Count the keyword uses with a search formula. Divide the second number by the first and multiply by 100. Simple formulas match exact text only so plural forms will not count." } },
        { "@type": "Question", "name": "Do synonyms and plural forms count toward density?", "acceptedAnswer": { "@type": "Answer", "text": "Most checkers count exact matches only. A plural form or a synonym counts as a separate term. That is why swapping some repeats for variants lowers the score while keeping the meaning. Semantic coverage still helps search engines understand the topic." } },
        { "@type": "Question", "name": "How often should I re-check old posts?", "acceptedAnswer": { "@type": "Answer", "text": "Re-check when you edit a post or when rankings slip. A yearly pass over your top pages is a sensible habit. Edits over time often add repeats by accident. Run the check after every big update." } }
      ]
    }
  ]
}

